import "core-js/modules/es6.string.link";
import "core-js/modules/es6.function.name";
import "core-js/modules/es6.number.constructor";
import { add, add2, update } from "@/api/data/uploadfiles";
import { Message } from "element-ui";
import { attrrelUpdate } from "@/api/cmdb/ciConfig";
import { Base64 } from "js-base64";
import website from "@/config/website";
import { getToken } from "@/util/auth";
import { attachRemove, removeFile } from "@/api/system/devInBound";
import { uploadFile1 } from "@/api/ictOperation/index";
export default {
  props: ['isShow', 'arrtId', 'type', 'formDetial'],
  data: function data() {
    return {
      saveLoading: false,
      statusList: null,
      title: '请导入数据文件',
      // 用户导入参数
      upload: {
        accept: ['doc', 'pdf', 'excel', 'rar', 'zip'],
        // 是否显示弹出层（用户导入）
        open: false,
        // 弹出层标题（用户导入）
        title: '',
        // 是否禁用上传
        isUploading: false,
        // 是否更新已经存在的用户数据
        updateSupport: 0,
        // 设置上传的请求头部
        headers: {
          Authorization: "Basic ".concat(Base64.encode("".concat(website.clientId, ":").concat(website.clientSecret))),
          'Idevelop-Auth': 'bearer ' + getToken()
        },
        // 上传的地址
        url: '#',
        imageUrl: null
      },
      isUploading: false,
      fileList: [],
      fileSize: 2 * 1024 * 1024,
      //文件大小

      loading: false,
      resObj: {},
      rules: {
        uploadFileName: [{
          required: true,
          message: '文件名称不能为空',
          trigger: 'blur'
        }],
        fileOrder: [{
          required: true,
          message: '排序序号不能为空',
          trigger: 'blur'
        }],
        fileUrl: [{
          required: true,
          message: '文件URL不能为空',
          trigger: 'blur'
        }],
        status: [{
          required: true,
          message: '状态不能为空',
          trigger: 'blur'
        }]
      }
    };
  },
  computed: {},
  mounted: function mounted() {
    if (!this.formDetial) {
      this.formDetial = {};
    }
    this.initTypes();
  },
  methods: {
    uploadFile2: function uploadFile2(params) {
      var file = params.file;
      var formData = new FormData();
      formData.append("file", file);
      uploadFile1(formData).then(function (res) {
        params.onSuccess(res);
      }).catch(function (error) {
        params.onError(error);
      });
    },
    initTypes: function initTypes() {
      this.statusList = [];
      this.statusList.push({
        name: '可用',
        id: 0
      });
      this.statusList.push({
        name: '不可用',
        id: 1
      });
    },
    aDowload: function aDowload(url, fileName) {
      var x = new window.XMLHttpRequest();
      x.open('GET', url, true);
      x.responseType = 'blob';
      x.onload = function () {
        var url2 = window.URL.createObjectURL(x.response);
        var a = document.createElement('a');
        a.href = url2;
        a.download = fileName;
        a.click();
        a.style.display = 'none';
        var timer = setTimeout(function () {
          a.remove();

          //释放blob对象
          URL.revokeObjectURL(url2);
          clearTimeout(timer);
        }, 1000);
      };
      x.send();
    },
    selectionChange: function selectionChange(val) {
      this.selectionList = val;
    },
    submit: function submit() {
      var _this = this;
      this.$refs.submitForm.validate(function (valid) {
        if (valid) {
          if (_this.type === 'add') {
            if (_this.$refs.upload.uploadFiles.length == 0) {
              _this.$alert("\u8BF7\u9009\u62E9\u8981\u4E0A\u4F20\u7684\u6587\u4EF6\uFF08\u683C\u5F0F ".concat(_this.upload.accept, "\uFF09"));
              return;
            }
          }
          if (_this.type == 'add') {
            // this.saveLoading = true;
            // add([this.formDetial]).then(res => {
            //   this.saveLoading = false
            //   this.$message.success('添加成功');
            //   this.$emit("close");
            //   this.$emit("refreshData");
            // });
            _this.loading = true;
            _this.$refs.upload.submit();
          } else if (_this.type == 'edit') {
            if (_this.$refs.upload.uploadFiles.length == 0) {
              //只更新基本信息
              update(_this.formDetial).then(function (res) {
                _this.saveLoading = false;
                _this.$message.success('修改成功');
                _this.$emit("close");
                _this.$emit("refreshData");
              });
            } else {
              //先删除旧文件,在更新新文件
              _this.loading = true;
              removeFile({
                originalName: _this.formDetial.localFileName
              }).then(function (res) {
                _this.$refs.upload.submit();
              });
            }
          }
        }
      });
    },
    handleChange: function handleChange(file, fileList) {
      var imgSize = Number(file.size / 1024 / 1024);
      if (imgSize > this.fileSize) {
        this.$message.error("\u6587\u4EF6\u5927\u5C0F\u4E0D\u80FD\u8D85\u8FC7".concat(this.fileSize, "Mb"));
        this.fileList = [];
      }
    },
    //上传之前操作(用于判断是否重名与格式限制)
    beforeUpload: function beforeUpload(file) {
      var acceptType = ['doc', 'pdf', 'excel', 'rar', 'zip'];
      var extension = file.name.substring(file.name.lastIndexOf('.') + 1);
      if (-1 === acceptType.indexOf(extension)) {
        this.$message.warning('支持文件格式' + acceptType + '！');
        return false;
      }
      // if (file.size/1024 > 5 * 1024) {
      //   this.$message.warning("当前文件超过5M，请修改！");
      //   return false;
      // }
    },
    // 文件上传中处理
    handleFileUploadProgress: function handleFileUploadProgress(event, file) {
      // this.upload.isUploading = true
    },
    // 文件上传成功处理
    // eslint-disable-next-line no-unused-vars
    handleFileSuccess: function handleFileSuccess(response, file, fileList) {
      var _this2 = this;
      // console.log(909090, response)
      if (this.type == 'add') {
        this.loading = true;
        this.formDetial['fileUrl'] = response.data.link;
        add(this.formDetial).then(function (res) {
          _this2.loading = true;
          _this2.$message.success('添加成功');
          _this2.$emit("close");
          _this2.$emit("refreshData");
        });
      } else if (this.type == 'edit') {
        this.loading = true;
        update(this.formDetial).then(function (res) {
          _this2.loading = true;
          _this2.$message.success('修改成功');
          _this2.$emit("close");
          _this2.$emit("refreshData");
        });
      }
    },
    handleFileError: function handleFileError(response, file, fileList) {
      this.$message.error(response);
    },
    handleRemove: function handleRemove(file) {
      var _this3 = this;
      if (!file.id) {
        this.resObj = {};
        return;
      }
      //删除旧文件
      this.fileList = [];
      var data = {
        ids: file.id
      };
      attachRemove(data).then(function (response) {
        if (response.code === 200) {
          _this3.fileList = [];
        } else {
          _this3.$message.error(response.msg);
        }
      });
      this.resObj = {};
    },
    handleExceed: function handleExceed() {
      this.$message.warning('图片上传数量已上限！');
    },
    getAccept: function getAccept() {
      var acc = '';
      for (var i = 0; i < this.upload.accept.length; i++) {
        acc += ".".concat(this.upload.accept[i]);
        if (i < this.upload.accept.length - 1) {
          acc += ',';
        }
      }
      return acc;
    },
    getTitle: function getTitle(type) {
      if (type == 'add') {
        return '新 增';
      } else if (type == 'edit') {
        return '更 新';
      }
      return null;
    }
  }
};
